package com.benkeyshop;

import com.formdev.flatlaf.FlatDarkLaf;
import javax.swing.*;import javax.swing.border.EmptyBorder;import javax.swing.table.DefaultTableModel;
import java.awt.*;import java.awt.event.*;import java.math.BigDecimal;import java.time.*;import java.time.format.DateTimeFormatter;import java.text.NumberFormat;import java.util.*;import java.util.List;

/** UI desktop; business logic dan akses data didelegasikan ke class OOP. */
public class Main extends JFrame {
 private final Color bg=new Color(17,24,27),panel=new Color(27,37,39),green=new Color(153,220,92),muted=new Color(166,181,177);
 private final ProductDAO products=new ProductDAO();private final SalesDAO sales=new SalesDAO();private final CartService cart=new CartService();private final ReceiptPrinter printer=new ReceiptPrinter();
 private final NumberFormat money=NumberFormat.getCurrencyInstance(new Locale("id","ID"));
 private final DefaultTableModel productModel=model("ID","SKU","Produk","Kategori","Harga","Stok"),cartModel=model("SKU","Produk","Harga","Qty","Subtotal"),salesModel=model("No. Struk","Tanggal","Pembeli","Subtotal","Diskon","Total");
 private JTable productTable,cartTable,salesTable;private JTextField cashierSearch,productSearch,buyer,paid,sku,name,category,price,stock,from,to;private JLabel status;private long selectedId=-1;
 public static void main(String[] a){SwingUtilities.invokeLater(()->{FlatDarkLaf.setup();new MainForm().setVisible(true);});}
 public Main(){super("BenkeyShop • OOP POS");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1200,780);setMinimumSize(new Dimension(1050,680));setLocationRelativeTo(null);UIManager.put("Component.arc",14);UIManager.put("Button.arc",16);setContentPane(ui());loadProducts("");refreshCart();refreshReport();dashboard();}
 private JPanel ui(){JPanel root=new JPanel(new BorderLayout(16,16));root.setBackground(bg);root.setBorder(new EmptyBorder(22,24,18,24));JPanel h=new JPanel(new BorderLayout());h.setOpaque(false);JPanel brand=new JPanel();brand.setOpaque(false);brand.setLayout(new BoxLayout(brand,BoxLayout.Y_AXIS));JLabel title=new JLabel("BenkeyShop");title.setForeground(green);title.setFont(new Font("SansSerif",1,30));JLabel sub=new JLabel("SMART RETAIL / POINT OF SALE");sub.setForeground(muted);brand.add(title);brand.add(sub);h.add(brand,BorderLayout.WEST);JLabel date=new JLabel(LocalDate.now().toString());date.setForeground(muted);h.add(date,BorderLayout.EAST);
 JTabbedPane tabs=new JTabbedPane();tabs.addTab("Ringkasan",dashboardPanel());tabs.addTab("Kasir",cashierPanel());tabs.addTab("Produk",productPanel());tabs.addTab("Laporan & Analisis",reportPanel());root.add(h,BorderLayout.NORTH);root.add(tabs,BorderLayout.CENTER);status=new JLabel("Siap");status.setForeground(muted);root.add(status,BorderLayout.SOUTH);return root;}
 private JPanel dashboardPanel(){JPanel p=panel(new BorderLayout(14,14));p.setBorder(new EmptyBorder(18,2,2,2));JPanel cards=new JPanel(new GridLayout(1,3,12,0));cards.setOpaque(false);cards.add(metric("PENJUALAN HARI INI","Rp 0"));cards.add(metric("TRANSAKSI HARI INI","0"));cards.add(metric("STOK MENIPIS","0"));JPanel info=panel(new BorderLayout());info.setBorder(new EmptyBorder(22,22,22,22));JLabel t=heading("Selamat datang di BenkeyShop");t.setForeground(green);info.add(t,BorderLayout.NORTH);info.add(new JLabel("Kasir desktop berbasis OOP • Keranjang • Struk • Laporan dan analisis"),BorderLayout.CENTER);p.add(cards,BorderLayout.NORTH);p.add(info,BorderLayout.CENTER);return p;}
 private JPanel metric(String text,String value){JPanel p=panel(new BorderLayout(6,6));p.setBorder(new EmptyBorder(18,18,18,18));JLabel a=new JLabel(text);a.setForeground(muted);JLabel b=new JLabel(value);b.setName("metric:"+text);b.setForeground(green);b.setFont(new Font("SansSerif",1,24));p.add(a,BorderLayout.NORTH);p.add(b,BorderLayout.CENTER);return p;}
 private JPanel cashierPanel(){JPanel p=panel(new BorderLayout(12,12));p.setBorder(new EmptyBorder(12,2,2,2));JPanel left=panel(new BorderLayout(8,8));left.setBorder(new EmptyBorder(14,14,14,14));cashierSearch=new JTextField();cashierSearch.putClientProperty("JTextField.placeholderText","Cari produk / SKU");cashierSearch.addKeyListener(new KeyAdapter(){public void keyReleased(KeyEvent e){loadProducts(cashierSearch.getText());}});productTable=new JTable(productModel);style(productTable);JButton add=accent("Tambah ke Keranjang");add.addActionListener(e->addCart());productTable.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){if(e.getClickCount()==2)addCart();}});left.add(cashierSearch,BorderLayout.NORTH);left.add(new JScrollPane(productTable),BorderLayout.CENTER);left.add(add,BorderLayout.SOUTH);
 JPanel right=panel(new BorderLayout(8,8));right.setBorder(new EmptyBorder(14,14,14,14));buyer=new JTextField();buyer.putClientProperty("JTextField.placeholderText","Nama pembeli (wajib)");JPanel top=new JPanel(new BorderLayout(5,5));top.setOpaque(false);top.add(heading("Keranjang"),BorderLayout.NORTH);top.add(buyer,BorderLayout.CENTER);cartTable=new JTable(cartModel);style(cartTable);JPanel buttons=new JPanel(new GridLayout(1,3,6,0));buttons.setOpaque(false);JButton plus=soft("+ Qty"),minus=soft("- Qty"),del=soft("Hapus");plus.addActionListener(e->qty(1));minus.addActionListener(e->qty(-1));del.addActionListener(e->removeCart());buttons.add(plus);buttons.add(minus);buttons.add(del);JPanel bottom=new JPanel();bottom.setOpaque(false);bottom.setLayout(new BoxLayout(bottom,BoxLayout.Y_AXIS));JLabel subtotal=new JLabel("Subtotal: Rp 0");subtotal.setName("cart-sub");subtotal.setForeground(muted);JLabel total=new JLabel("TOTAL Rp 0");total.setName("cart-total");total.setForeground(green);total.setFont(new Font("SansSerif",1,21));paid=new JTextField();paid.putClientProperty("JTextField.placeholderText","Uang dibayar, mis. 50000");JButton pay=accent("Bayar & Cetak Struk");pay.addActionListener(e->checkout());JButton clear=soft("Kosongkan Keranjang");clear.addActionListener(e->{cart.clear();refreshCart();});bottom.add(subtotal);bottom.add(total);bottom.add(Box.createVerticalStrut(8));bottom.add(paid);bottom.add(Box.createVerticalStrut(8));bottom.add(pay);bottom.add(clear);JPanel south=new JPanel(new BorderLayout(6,6));south.setOpaque(false);south.add(buttons,BorderLayout.NORTH);south.add(bottom,BorderLayout.CENTER);right.add(top,BorderLayout.NORTH);right.add(new JScrollPane(cartTable),BorderLayout.CENTER);right.add(south,BorderLayout.SOUTH);JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,left,right);split.setResizeWeight(.5);split.setBorder(null);p.add(split);return p;}
 private JPanel productPanel(){JPanel p=panel(new BorderLayout(10,10));p.setBorder(new EmptyBorder(12,2,2,2));JPanel form=panel(new GridLayout(1,5,7,7));form.setBorder(new EmptyBorder(12,12,12,12));sku=new JTextField();name=new JTextField();category=new JTextField();price=new JTextField();stock=new JTextField();form.add(field("SKU",sku));form.add(field("Nama",name));form.add(field("Kategori",category));form.add(field("Harga",price));form.add(field("Stok",stock));JButton save=accent("Simpan / Perbarui"),fresh=soft("Form Baru"),del=soft("Hapus Produk");save.addActionListener(e->saveProduct());fresh.addActionListener(e->clearForm());del.addActionListener(e->deleteProduct());JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);actions.add(save);actions.add(fresh);actions.add(del);JPanel north=new JPanel(new BorderLayout());north.setOpaque(false);north.add(form);north.add(actions,BorderLayout.SOUTH);JPanel table=panel(new BorderLayout(6,6));productSearch=new JTextField();productSearch.putClientProperty("JTextField.placeholderText","Cari SKU, nama, kategori");productSearch.addKeyListener(new KeyAdapter(){public void keyReleased(KeyEvent e){loadProducts(productSearch.getText());}});table.add(productSearch,BorderLayout.NORTH);JTable t=new JTable(productModel);style(t);t.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting())fillForm(t);});table.add(new JScrollPane(t));p.add(north,BorderLayout.NORTH);p.add(table);return p;}
 private JPanel reportPanel(){JPanel p=panel(new BorderLayout(8,8));p.setBorder(new EmptyBorder(12,2,2,2));JPanel f=panel(new FlowLayout(FlowLayout.LEFT,8,8));from=new JTextField(LocalDate.now().withDayOfMonth(1).toString(),10);to=new JTextField(LocalDate.now().toString(),10);JButton run=accent("Tampilkan Laporan"),csv=soft("Ekspor CSV");run.addActionListener(e->refreshReport());csv.addActionListener(e->exportCsv());f.add(new JLabel("Dari YYYY-MM-DD"));f.add(from);f.add(new JLabel("Sampai"));f.add(to);f.add(run);f.add(csv);salesTable=new JTable(salesModel);style(salesTable);p.add(f,BorderLayout.NORTH);p.add(new JScrollPane(salesTable));return p;}
 private JPanel panel(LayoutManager l){JPanel p=new JPanel(l);p.setBackground(panel);return p;}private JLabel heading(String s){JLabel l=new JLabel(s);l.setForeground(Color.WHITE);l.setFont(new Font("SansSerif",1,17));return l;}private JButton accent(String s){JButton b=new JButton(s);b.setBackground(green);b.setForeground(new Color(20,29,24));return b;}private JButton soft(String s){JButton b=new JButton(s);b.setBackground(new Color(43,58,57));b.setForeground(Color.WHITE);return b;}private JPanel field(String s,JComponent c){JPanel p=new JPanel(new BorderLayout(3,3));p.setOpaque(false);JLabel l=new JLabel(s);l.setForeground(muted);p.add(l,BorderLayout.NORTH);p.add(c);return p;}private void style(JTable t){t.setRowHeight(29);t.setShowGrid(false);t.setSelectionBackground(new Color(57,78,59));t.getTableHeader().setBackground(new Color(37,50,49));t.getTableHeader().setForeground(green);}private static DefaultTableModel model(String...s){return new DefaultTableModel(s,0){public boolean isCellEditable(int r,int c){return false;}};}private String fmt(BigDecimal n){return money.format(n).replace(",00","");}private void msg(String s){JOptionPane.showMessageDialog(this,s,"BenkeyShop",JOptionPane.INFORMATION_MESSAGE);}private void err(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Kesalahan",JOptionPane.ERROR_MESSAGE);}
 private void loadProducts(String q){try{productModel.setRowCount(0);for(Product p:products.search(q))productModel.addRow(new Object[]{p.getId(),p.getSku(),p.getName(),p.getCategory(),fmt(p.getPrice()),p.getStock()});}catch(Exception e){if(status!=null)status.setText("Database belum terhubung: periksa XAMPP/db.properties");}}
 private Product selected(JTable t)throws Exception{int r=t.getSelectedRow();if(r<0)return null;return products.findById(Long.parseLong(productModel.getValueAt(t.convertRowIndexToModel(r),0).toString()));}
 private void addCart(){try{Product p=selected(productTable);if(p==null){msg("Pilih produk dahulu.");return;}cart.add(p);refreshCart();}catch(Exception e){err(e);}}
 private void refreshCart(){cartModel.setRowCount(0);for(CartItem i:cart.getItems())cartModel.addRow(new Object[]{i.getProduct().getSku(),i.getProduct().getName(),fmt(i.getProduct().getPrice()),i.getQuantity(),fmt(i.getSubtotal())});label("cart-sub","Subtotal: "+fmt(cart.getSubtotal()));label("cart-total","TOTAL "+fmt(cart.getSubtotal()));}
 private void label(String n,String v){findLabel(this,n,v);}private void findLabel(Container c,String n,String v){for(Component x:c.getComponents()){if(x instanceof JLabel l&&n.equals(l.getName()))l.setText(v);if(x instanceof Container cc)findLabel(cc,n,v);}}
 private long cartSelectedId(){int r=cartTable.getSelectedRow();if(r<0)return -1;return new ArrayList<>(cart.snapshot().keySet()).get(r);}private void qty(int d){long id=cartSelectedId();if(id<0)return;try{cart.changeQuantity(id,d);refreshCart();}catch(Exception e){err(e);}}private void removeCart(){long id=cartSelectedId();if(id>0){cart.remove(id);refreshCart();}}
 private void checkout(){if(cart.isEmpty()){msg("Keranjang kosong.");return;}if(buyer.getText().trim().isEmpty()){msg("Nama pembeli wajib diisi.");return;}BigDecimal sub=cart.getSubtotal(),paidAmount;try{paidAmount=new BigDecimal(paid.getText().trim().replace(".","").replace(",",""));if(paidAmount.compareTo(sub)<0){msg("Pembayaran kurang.");return;}}catch(Exception e){msg("Masukkan pembayaran sebagai angka, mis. 50000.");return;}String no="BKS-"+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyMMddHHmmssSSS"));List<SaleLine> lines=new ArrayList<>();for(CartItem i:cart.getItems())lines.add(new SaleLine(i.getProduct().getId(),i.getProduct().getSku(),i.getProduct().getName(),i.getProduct().getPrice(),i.getQuantity()));Sale sale=new Sale(no,buyer.getText().trim(),LocalDateTime.now(),sub,BigDecimal.ZERO,sub,paidAmount,paidAmount.subtract(sub),lines);try{sales.save(sale,cart.snapshot());String receipt=printer.format(sale);JTextArea area=new JTextArea(receipt,23,40);area.setFont(new Font(Font.MONOSPACED,0,12));area.setEditable(false);if(JOptionPane.showConfirmDialog(this,new JScrollPane(area),"Transaksi berhasil",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)printer.print(receipt);cart.clear();buyer.setText("");paid.setText("");refreshCart();loadProducts("");refreshReport();dashboard();status.setText("Transaksi tersimpan: "+no);}catch(Exception e){err(e);}}
 private void saveProduct(){try{String a=sku.getText().trim(),b=name.getText().trim(),c=category.getText().trim();BigDecimal d=new BigDecimal(price.getText().trim());int st=Integer.parseInt(stock.getText().trim());if(a.isEmpty()||b.isEmpty()||c.isEmpty()||d.signum()<0||st<0)throw new IllegalArgumentException("Lengkapi data produk dengan benar.");products.save(new Product(selectedId,a,b,c,d,st));clearForm();loadProducts("");dashboard();}catch(Exception e){err(e);}}
 private void fillForm(JTable t){try{Product p=selected(t);if(p==null)return;selectedId=p.getId();sku.setText(p.getSku());name.setText(p.getName());category.setText(p.getCategory());price.setText(p.getPrice().toPlainString());stock.setText(String.valueOf(p.getStock()));}catch(Exception e){err(e);}}
 private void clearForm(){selectedId=-1;if(sku!=null){sku.setText("");name.setText("");category.setText("");price.setText("");stock.setText("");}}
 private void deleteProduct(){if(selectedId<=0){msg("Pilih produk dari tabel produk terlebih dahulu.");return;}if(JOptionPane.showConfirmDialog(this,"Hapus produk? Riwayat lama tetap utuh.","Konfirmasi",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{products.delete(selectedId);clearForm();loadProducts("");dashboard();}catch(Exception e){err(e);}}
 private void refreshReport(){if(salesTable==null)return;try{LocalDate a=LocalDate.parse(from.getText().trim()),b=LocalDate.parse(to.getText().trim());if(b.isBefore(a))throw new IllegalArgumentException();salesModel.setRowCount(0);for(Object[] r:sales.report(a,b))salesModel.addRow(new Object[]{r[0],r[1],r[2],fmt((BigDecimal)r[3]),fmt((BigDecimal)r[4]),fmt((BigDecimal)r[5])});BigDecimal[] s=sales.summary(a,b);status.setText("Analisis "+a+" s.d. "+b+" • "+s[0].toBigInteger()+" transaksi • omzet "+fmt(s[1])+" • rata-rata "+fmt(s[2]));}catch(Exception e){if(status!=null)status.setText("Tanggal harus YYYY-MM-DD dan koneksi database aktif.");}}
 private void dashboard(){try{BigDecimal[] s=sales.today();setMetric("PENJUALAN HARI INI",fmt(s[1]));setMetric("TRANSAKSI HARI INI",s[0].toBigInteger().toString());int low=0;for(Product p:products.search(""))if(p.getStock()<=5)low++;setMetric("STOK MENIPIS",String.valueOf(low));}catch(Exception e){if(status!=null)status.setText("Database belum terhubung; jalankan MySQL di XAMPP.");}}
 private void setMetric(String k,String v){findMetric(this,k,v);}private void findMetric(Container c,String k,String v){for(Component x:c.getComponents()){if(x instanceof JLabel l&&("metric:"+k).equals(l.getName()))l.setText(v);if(x instanceof Container cc)findMetric(cc,k,v);}}
 private void exportCsv(){JFileChooser ch=new JFileChooser();ch.setSelectedFile(new java.io.File("laporan-benkeyshop.csv"));if(ch.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;try(java.io.PrintWriter out=new java.io.PrintWriter(ch.getSelectedFile(),"UTF-8")){out.println("No Struk,Tanggal,Pembeli,Subtotal,Diskon,Total");for(int i=0;i<salesModel.getRowCount();i++){for(int j=0;j<salesModel.getColumnCount();j++){if(j>0)out.print(',');out.print("\""+String.valueOf(salesModel.getValueAt(i,j)).replace("\"","\"\"")+"\"");}out.println();}msg("CSV diekspor.");}catch(Exception e){err(e);}}
}
